"""Modern retry wrapper for migrated Meridian CRM integrations."""


class TransientError(Exception):
    """A retryable transport failure, such as a timeout or server error."""


class PermanentError(Exception):
    """A non-retryable transport failure, such as a client or auth error."""


def call_with_retry(endpoint_cfg: dict, transport) -> dict:
    """Call an injected transport using the endpoint's configured retry budget."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    max_attempts = endpoint_cfg["retry"] + 1

    for attempts in range(1, max_attempts + 1):
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts == max_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }

    raise RuntimeError("Unreachable retry state")
